/**
 * The project's Preview: its settings or `null`, the hostname it will be served at (or why there is none), whether the repository is ready to be read, its state, the build that runs, the latest build and whether an environment controller is connected.
 */
export const getPreview = <ThrowOnError extends boolean = false>(options: Options<GetPreviewData, ThrowOnError>): RequestResult<GetPreviewResponses, GetPreviewErrors, ThrowOnError> => (options.client ?? client).get<GetPreviewResponses, GetPreviewErrors, ThrowOnError>({ url: '/api/projects/{id}/preview', ...options });

/**
 * Removes the project's Preview settings. Removing settings that are not set changes nothing.
 */
export const removePreviewSettings = <ThrowOnError extends boolean = false>(options: Options<RemovePreviewSettingsData, ThrowOnError>): RequestResult<RemovePreviewSettingsResponses, RemovePreviewSettingsErrors, ThrowOnError> => (options.client ?? client).delete<RemovePreviewSettingsResponses, RemovePreviewSettingsErrors, ThrowOnError>({ url: '/api/projects/{id}/preview/settings', ...options });

/**
 * Sets the project's Preview settings, or replaces them. Studio reads the Compose file from the Integration branch at the commit its Clone holds, judges it, and saves only when it is accepted. Published ports in the file are removed when the Preview starts; `removedPorts` lists them.
 */
export const savePreviewSettings = <ThrowOnError extends boolean = false>(options: Options<SavePreviewSettingsData, ThrowOnError>): RequestResult<SavePreviewSettingsResponses, SavePreviewSettingsErrors, ThrowOnError> => (options.client ?? client).put<SavePreviewSettingsResponses, SavePreviewSettingsErrors, ThrowOnError>({
    url: '/api/projects/{id}/preview/settings',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Asks the environment controller to build and start the project's Preview from the commit its Clone holds. The Compose file is judged again at that commit first. The answer is the queued build; the Preview and the build log are read from the other routes.
 */
export const requestPreviewBuild = <ThrowOnError extends boolean = false>(options: Options<RequestPreviewBuildData, ThrowOnError>): RequestResult<RequestPreviewBuildResponses, RequestPreviewBuildErrors, ThrowOnError> => (options.client ?? client).post<RequestPreviewBuildResponses, RequestPreviewBuildErrors, ThrowOnError>({ url: '/api/projects/{id}/preview/builds', ...options });

/**
 * Asks the environment controller to stop the running Preview of the project. The Preview is `stopping` until it has; its volumes are kept. The answer is the Preview.
 */
export const stopPreview = <ThrowOnError extends boolean = false>(options: Options<StopPreviewData, ThrowOnError>): RequestResult<StopPreviewResponses, StopPreviewErrors, ThrowOnError> => (options.client ?? client).post<StopPreviewResponses, StopPreviewErrors, ThrowOnError>({ url: '/api/projects/{id}/preview/stop', ...options });

/**
 * Removes the volumes of the Preview for good, and everything else the controller keeps of it. A running Preview is rebuilt from the commit it runs. The answer is the Preview.
 */
export const resetPreviewData = <ThrowOnError extends boolean = false>(options: Options<ResetPreviewDataData, ThrowOnError>): RequestResult<ResetPreviewDataResponses, ResetPreviewDataErrors, ThrowOnError> => (options.client ?? client).post<ResetPreviewDataResponses, ResetPreviewDataErrors, ThrowOnError>({ url: '/api/projects/{id}/preview/reset-data', ...options });

